Contents of file frontend/src/styles/App.css:

1 | /* ============================================================
2 |    App.css — DebugFlow dark developer-tool theme
3 |    ============================================================ */
4 | 
5 | /* ── CSS Variables ─────────────────────────────────────────── */
6 | :root {
7 |   --bg:          #0d1117;
8 |   --bg-panel:    #161b22;
9 |   --bg-surface:  #1c2128;
10 |   --bg-code:     #0d1117;
11 |   --border:      #30363d;
12 |   --border-focus:#58a6ff;
13 |   --text:        #c9d1d9;
14 |   --text-muted:  #6e7681;
15 |   --text-heading:#e6edf3;
16 |   --accent:      #58a6ff;
17 |   --accent-dark: #1f6feb;
18 |   --green:       #3fb950;
19 |   --green-bg:    #0d4429;
20 |   --red:         #f85149;
21 |   --red-bg:      #3b0a0a;
22 |   --yellow:      #d29922;
23 |   --yellow-bg:   #3d2d00;
24 |   --diff-add-bg: #0d4429;
25 |   --diff-del-bg: #3b0a0a;
26 |   --diff-hunk:   #1f6feb;
27 | 
28 |   --font-sans:   -apple-system, "Segoe UI", system-ui, sans-serif;
29 |   --font-mono:   "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
30 | 
31 |   --radius:      6px;
32 |   --radius-lg:   10px;
33 |   --shadow:      0 1px 3px rgba(0,0,0,.4);
34 | }
35 | 
36 | /* ── Reset / Base ───────────────────────────────────────────── */
37 | *,
38 | *::before,
39 | *::after {
40 |   box-sizing: border-box;
41 |   margin: 0;
42 |   padding: 0;
43 | }
44 | 
45 | html {
46 |   font-size: 15px;
47 |   -webkit-text-size-adjust: 100%;
48 | }
49 | 
50 | body {
51 |   background-color: var(--bg);
52 |   color: var(--text);
53 |   font-family: var(--font-sans);
54 |   line-height: 1.6;
55 |   min-height: 100vh;
56 | }
57 | 
58 | /* Visually hidden helper for screen-reader labels */
59 | .sr-only {
60 |   position: absolute;
61 |   width: 1px;
62 |   height: 1px;
63 |   padding: 0;
64 |   margin: -1px;
65 |   overflow: hidden;
66 |   clip: rect(0,0,0,0);
67 |   white-space: nowrap;
68 |   border: 0;
69 | }
70 | 
71 | /* ── Header ─────────────────────────────────────────────────── */
72 | .app-header {
73 |   background: var(--bg-panel);
74 |   border-bottom: 1px solid var(--border);
75 |   padding: 0.9rem 1.5rem;
76 |   display: flex;
77 |   align-items: center;
78 |   justify-content: space-between;
79 |   position: sticky;
80 |   top: 0;
81 |   z-index: 10;
82 | }
83 | 
84 | .header-brand {
85 |   display: flex;
86 |   align-items: center;
87 |   gap: 0.75rem;
88 | }
89 | 
90 | .header-logo {
91 |   font-size: 1.6rem;
92 |   color: var(--accent);
93 | }
94 | 
95 | .header-title {
96 |   font-size: 1.25rem;
97 |   font-weight: 700;
98 |   color: var(--text-heading);
99 |   letter-spacing: -0.01em;
100 | }
101 | 
102 | .header-tagline {
103 |   font-size: 0.78rem;
104 |   color: var(--text-muted);
105 | }
106 | 
107 | /* Backend status pill */
108 | .backend-status {
109 |   display: flex;
110 |   align-items: center;
111 |   gap: 0.4rem;
112 |   font-size: 0.78rem;
113 |   padding: 0.3rem 0.7rem;
114 |   border-radius: 999px;
115 |   border: 1px solid var(--border);
116 |   background: var(--bg-surface);
117 | }
118 | 
119 | .status-dot {
120 |   width: 7px;
121 |   height: 7px;
122 |   border-radius: 50%;
123 |   display: inline-block;
124 |   flex-shrink: 0;
125 | }
126 | 
127 | .backend-status--online  .status-dot { background: var(--green); }
128 | .backend-status--offline .status-dot { background: var(--red); }
129 | .backend-status--checking .status-dot { background: var(--yellow); }
130 | .backend-status--online  { color: var(--green); border-color: var(--green-bg); }
131 | .backend-status--offline { color: var(--red);   border-color: var(--red-bg); }
132 | 
133 | /* ── Main layout ────────────────────────────────────────────── */
134 | .app-main {
135 |   max-width: 1200px;
136 |   margin: 0 auto;
137 |   padding: 1.5rem 1.5rem 3rem;
138 |   display: flex;
139 |   flex-direction: column;
140 |   gap: 1.25rem;
141 | }
142 | 
143 | .input-row {
144 |   display: grid;
145 |   grid-template-columns: 1fr 1fr;
146 |   gap: 1.25rem;
147 | }
148 | 
149 | @media (max-width: 860px) {
150 |   .input-row {
151 |     grid-template-columns: 1fr;
152 |   }
153 | }
154 | 
155 | /* ── Panels ─────────────────────────────────────────────────── */
156 | .panel {
157 |   background: var(--bg-panel);
158 |   border: 1px solid var(--border);
159 |   border-radius: var(--radius-lg);
160 |   padding: 1.1rem 1.25rem;
161 |   display: flex;
162 |   flex-direction: column;
163 |   gap: 0.75rem;
164 | }
165 | 
166 | .panel--result {
167 |   border-left: 3px solid var(--accent-dark);
168 | }
169 | 
170 | .panel-header {
171 |   display: flex;
172 |   align-items: center;
173 |   justify-content: space-between;
174 |   flex-wrap: wrap;
175 |   gap: 0.5rem;
176 | }
177 | 
178 | .panel-subheader {
179 |   display: flex;
180 |   align-items: center;
181 |   justify-content: space-between;
182 |   flex-wrap: wrap;
183 |   gap: 0.5rem;
184 | }
185 | 
186 | .panel-title {
187 |   font-size: 0.92rem;
188 |   font-weight: 600;
189 |   color: var(--text-heading);
190 |   text-transform: uppercase;
191 |   letter-spacing: 0.05em;
192 | }
193 | 
194 | .panel-actions {
195 |   display: flex;
196 |   align-items: center;
197 |   gap: 0.4rem;
198 |   flex-wrap: wrap;
199 | }
200 | 
201 | .panel-hint {
202 |   font-size: 0.75rem;
203 |   color: var(--text-muted);
204 | }
205 | 
206 | .panel-footer {
207 |   margin-top: 0.5rem;
208 |   padding-top: 0.75rem;
209 |   border-top: 1px solid var(--border);
210 |   display: flex;
211 |   align-items: center;
212 |   flex-wrap: wrap;
213 |   gap: 0.75rem;
214 | }
215 | 
216 | /* ── Buttons ─────────────────────────────────────────────────── */
217 | .btn {
218 |   cursor: pointer;
219 |   border: none;
220 |   border-radius: var(--radius);
221 |   font-family: var(--font-sans);
222 |   font-size: 0.85rem;
223 |   font-weight: 500;
224 |   padding: 0.45rem 0.9rem;
225 |   transition: opacity 0.1s, background 0.1s;
226 |   white-space: nowrap;
227 | }
228 | 
229 | .btn:disabled {
230 |   opacity: 0.45;
231 |   cursor: not-allowed;
232 | }
233 | 
234 | .btn--primary {
235 |   background: var(--accent-dark);
236 |   color: #fff;
237 | }
238 | .btn--primary:not(:disabled):hover { background: var(--accent); }
239 | 
240 | .btn--secondary {
241 |   background: var(--bg-surface);
242 |   color: var(--text);
243 |   border: 1px solid var(--border);
244 | }
245 | .btn--secondary:not(:disabled):hover { border-color: var(--accent); color: var(--accent); }
246 | 
247 | .btn--ghost {
248 |   background: transparent;
249 |   color: var(--text-muted);
250 |   border: 1px solid transparent;
251 | }
252 | .btn--ghost:not(:disabled):hover { color: var(--text); border-color: var(--border); }
253 | 
254 | .btn--accent {
255 |   background: var(--green-bg);
256 |   color: var(--green);
257 |   border: 1px solid var(--green);
258 | }
259 | .btn--accent:not(:disabled):hover { background: #185c2e; }
260 | 
261 | .btn--sm {
262 |   font-size: 0.78rem;
263 |   padding: 0.3rem 0.65rem;
264 | }
265 | 
266 | /* ── Textareas / Code editor ─────────────────────────────────── */
267 | .code-textarea {
268 |   width: 100%;
269 |   background: var(--bg-code);
270 |   border: 1px solid var(--border);
271 |   border-radius: var(--radius);
272 |   color: var(--text);
273 |   font-family: var(--font-mono);
274 |   font-size: 0.8rem;
275 |   line-height: 1.55;
276 |   padding: 0.75rem;
277 |   resize: vertical;
278 |   outline: none;
279 |   tab-size: 4;
280 | }
281 | 
282 | .code-textarea:focus {
283 |   border-color: var(--border-focus);
284 |   box-shadow: 0 0 0 2px rgba(88,166,255,.15);
285 | }
286 | 
287 | .code-textarea--error {
288 |   border-color: #3b1a1a;
289 | }
290 | 
291 | .code-textarea--error:focus {
292 |   border-color: var(--red);
293 |   box-shadow: 0 0 0 2px rgba(248,81,73,.15);
294 | }
295 | 
296 | .analyze-row {
297 |   display: flex;
298 |   align-items: center;
299 |   gap: 0.75rem;
300 |   flex-wrap: wrap;
301 | }
302 | 
303 | /* ── Workflow Status ─────────────────────────────────────────── */
304 | .workflow-status {
305 |   display: flex;
306 |   align-items: center;
307 |   background: var(--bg-panel);
308 |   border: 1px solid var(--border);
309 |   border-radius: var(--radius-lg);
310 |   padding: 0.85rem 1.25rem;
311 |   overflow-x: auto;
312 | }
313 | 
314 | .workflow-step {
315 |   display: flex;
316 |   align-items: center;
317 |   gap: 0.45rem;
318 |   flex-shrink: 0;
319 | }
320 | 
321 | .workflow-node {
322 |   width: 26px;
323 |   height: 26px;
324 |   border-radius: 50%;
325 |   display: flex;
326 |   align-items: center;
327 |   justify-content: center;
328 |   font-size: 0.72rem;
329 |   font-weight: 600;
330 |   border: 2px solid var(--border);
331 |   color: var(--text-muted);
332 |   background: var(--bg-surface);
333 |   flex-shrink: 0;
334 | }
335 | 
336 | .workflow-label {
337 |   font-size: 0.78rem;
338 |   color: var(--text-muted);
339 |   white-space: nowrap;
340 | }
341 | 
342 | .workflow-connector {
343 |   width: 32px;
344 |   height: 2px;
345 |   margin: 0 0.35rem;
346 |   border-radius: 1px;
347 |   flex-shrink: 0;
348 | }
349 | 
350 | .workflow-connector--done    { background: var(--green); }
351 | .workflow-connector--pending { background: var(--border); }
352 | 
353 | .workflow-step--active .workflow-node {
354 |   border-color: var(--accent);
355 |   background: rgba(31,111,235,0.15);
356 |   color: var(--accent);
357 | }
358 | .workflow-step--active .workflow-label {
359 |   color: var(--accent);
360 |   font-weight: 600;
361 | }
362 | 
363 | .workflow-step--done .workflow-node {
364 |   border-color: var(--green);
365 |   background: var(--green-bg);
366 |   color: var(--green);
367 | }
368 | .workflow-step--done .workflow-label {
369 |   color: var(--green);
370 | }
371 | 
372 | /* ── Analysis Panel ──────────────────────────────────────────── */
373 | .analysis-grid {
374 |   display: grid;
375 |   grid-template-columns: 1fr 1fr;
376 |   gap: 0.65rem;
377 | }
378 | 
379 | @media (max-width: 600px) {
380 |   .analysis-grid { grid-template-columns: 1fr; }
381 | }
382 | 
383 | .analysis-field {
384 |   background: var(--bg-surface);
385 |   border: 1px solid var(--border);
386 |   border-radius: var(--radius);
387 |   padding: 0.55rem 0.75rem;
388 |   display: flex;
389 |   flex-direction: column;
390 |   gap: 0.15rem;
391 | }
392 | 
393 | .analysis-field--wide {
394 |   grid-column: 1 / -1;
395 | }
396 | 
397 | .field--highlight {
398 |   border-color: var(--accent-dark);
399 |   background: rgba(31,111,235,0.08);
400 | }
401 | 
402 | .field-label {
403 |   font-size: 0.68rem;
404 |   text-transform: uppercase;
405 |   letter-spacing: 0.07em;
406 |   color: var(--text-muted);
407 | }
408 | 
409 | .field-value {
410 |   font-size: 0.85rem;
411 |   color: var(--text-heading);
412 |   word-break: break-word;
413 | }
414 | 
415 | .field-value--mono {
416 |   font-family: var(--font-mono);
417 |   color: var(--accent);
418 | }
419 | 
420 | .confidence-badge {
421 |   font-size: 0.75rem;
422 |   font-weight: 600;
423 |   padding: 0.25rem 0.65rem;
424 |   border-radius: 999px;
425 | }
426 | 
427 | .confidence--high   { background: var(--green-bg);  color: var(--green);  }
428 | .confidence--medium { background: var(--yellow-bg); color: var(--yellow); }
429 | .confidence--low    { background: var(--red-bg);    color: var(--red);    }
430 | 
431 | /* ── Fix Panel ───────────────────────────────────────────────── */
432 | .fix-explanation,
433 | .fix-proposed-change {
434 |   background: var(--bg-surface);
435 |   border: 1px solid var(--border);
436 |   border-radius: var(--radius);
437 |   padding: 0.65rem 0.85rem;
438 | }
439 | 
440 | .subsection-title {
441 |   font-size: 0.72rem;
442 |   text-transform: uppercase;
443 |   letter-spacing: 0.07em;
444 |   color: var(--text-muted);
445 |   margin-bottom: 0.3rem;
446 | }
447 | 
448 | .explanation-text {
449 |   font-size: 0.85rem;
450 |   color: var(--text);
451 |   line-height: 1.6;
452 | }
453 | 
454 | /* Code tabs */
455 | .code-tabs {
456 |   display: flex;
457 |   gap: 0;
458 |   border-bottom: 1px solid var(--border);
459 | }
460 | 
461 | .code-tab {
462 |   background: transparent;
463 |   border: none;
464 |   border-bottom: 2px solid transparent;
465 |   color: var(--text-muted);
466 |   cursor: pointer;
467 |   font-size: 0.8rem;
468 |   padding: 0.45rem 0.85rem;
469 |   font-family: var(--font-sans);
470 | }
471 | 
472 | .code-tab:hover { color: var(--text); }
473 | 
474 | .code-tab--active {
475 |   color: var(--accent);
476 |   border-bottom-color: var(--accent);
477 |   font-weight: 600;
478 | }
479 | 
480 | /* Code blocks */
481 | .code-block {
482 |   background: var(--bg-code);
483 |   border: 1px solid var(--border);
484 |   border-radius: var(--radius);
485 |   padding: 0.75rem;
486 |   font-family: var(--font-mono);
487 |   font-size: 0.78rem;
488 |   line-height: 1.55;
489 |   overflow-x: auto;
490 |   white-space: pre;
491 |   color: var(--text);
492 | }
493 | 
494 | .code-block--compact { font-size: 0.75rem; }
495 | .code-block--fixed { border-color: var(--green); }
496 | .code-block--stderr { color: var(--red); }
497 | 
498 | /* Diff colouring */
499 | .diff-add    { display: block; background: var(--diff-add-bg); color: var(--green); }
500 | .diff-remove { display: block; background: var(--diff-del-bg); color: var(--red); }
501 | .diff-hunk   { display: block; color: var(--diff-hunk); }
502 | 
503 | .applied-notice {
504 |   display: flex;
505 |   align-items: center;
506 |   flex-wrap: wrap;
507 | }
508 | 
509 | /* ── Test Results ────────────────────────────────────────────── */
510 | .test-results {
511 |   border-top: 1px solid var(--border);
512 |   padding-top: 0.75rem;
513 |   display: flex;
514 |   flex-direction: column;
515 |   gap: 0.65rem;
516 | }
517 | 
518 | .test-summary-row {
519 |   display: flex;
520 |   align-items: center;
521 |   gap: 0.75rem;
522 |   flex-wrap: wrap;
523 | }
524 | 
525 | .test-status-badge {
526 |   font-size: 0.82rem;
527 |   font-weight: 700;
528 |   padding: 0.3rem 0.75rem;
529 |   border-radius: var(--radius);
530 | }
531 | 
532 | .test-status-badge--pass { background: var(--green-bg); color: var(--green); }
533 | .test-status-badge--fail { background: var(--red-bg);   color: var(--red);   }
534 | 
535 | .test-counts {
536 |   font-size: 0.8rem;
537 |   color: var(--text-muted);
538 | }
539 | 
540 | .tests-passed { color: var(--green); }
541 | .tests-failed { color: var(--red); }
542 | .tests-errors { color: var(--yellow); }
543 | 
544 | .return-code {
545 |   font-size: 0.75rem;
546 |   color: var(--text-muted);
547 |   font-family: var(--font-mono);
548 |   margin-left: auto;
549 | }
550 | 
551 | .test-summary-text { }
552 | 
553 | .test-output {
554 |   display: flex;
555 |   flex-direction: column;
556 |   gap: 0.5rem;
557 | }
558 | 
559 | .output-label {
560 |   font-size: 0.72rem;
561 |   text-transform: uppercase;
562 |   letter-spacing: 0.07em;
563 |   color: var(--text-muted);
564 |   margin-bottom: 0.2rem;
565 | }
566 | 
567 | /* ── Badges ─────────────────────────────────────────────────── */
568 | .badge {
569 |   font-size: 0.72rem;
570 |   font-weight: 600;
571 |   padding: 0.2rem 0.55rem;
572 |   border-radius: 999px;
573 | }
574 | 
575 | .badge--green  { background: var(--green-bg);  color: var(--green);  }
576 | .badge--yellow { background: var(--yellow-bg); color: var(--yellow); }
577 | 
578 | /* ── Banners ─────────────────────────────────────────────────── */
579 | .error-banner {
580 |   background: var(--red-bg);
581 |   border: 1px solid var(--red);
582 |   border-radius: var(--radius);
583 |   color: var(--red);
584 |   font-size: 0.85rem;
585 |   padding: 0.65rem 0.85rem;
586 |   display: flex;
587 |   align-items: center;
588 |   gap: 0.5rem;
589 | }
590 | 
591 | .error-banner strong { flex-shrink: 0; }
592 | 
593 | .error-banner-close {
594 |   margin-left: auto;
595 |   background: none;
596 |   border: none;
597 |   color: var(--red);
598 |   cursor: pointer;
599 |   font-size: 0.9rem;
600 |   padding: 0.1rem 0.3rem;
601 |   border-radius: 3px;
602 |   flex-shrink: 0;
603 | }
604 | .error-banner-close:hover { background: rgba(248,81,73,.2); }
605 | 
606 | .warn-banner {
607 |   background: var(--yellow-bg);
608 |   border: 1px solid var(--yellow);
609 |   border-radius: var(--radius);
610 |   color: var(--yellow);
611 |   font-size: 0.82rem;
612 |   padding: 0.6rem 0.85rem;
613 | }
614 | 
615 | .warn-banner code {
616 |   background: rgba(0,0,0,.2);
617 |   padding: 0.1rem 0.35rem;
618 |   border-radius: 3px;
619 |   font-family: var(--font-mono);
620 |   font-size: 0.8em;
621 | }
622 | 
623 | /* ── Info box ────────────────────────────────────────────────── */
624 | .info-box--warning {
625 |   background: var(--yellow-bg);
626 |   border: 1px solid var(--yellow);
627 |   border-radius: var(--radius);
628 |   color: var(--yellow);
629 |   font-size: 0.82rem;
630 |   padding: 0.6rem 0.85rem;
631 | }
632 | 
633 | /* ── Footer ─────────────────────────────────────────────────── */
634 | .app-footer {
635 |   text-align: center;
636 |   font-size: 0.72rem;
637 |   color: var(--text-muted);
638 |   padding: 1.5rem 1rem;
639 |   border-top: 1px solid var(--border);
640 | }
641 |

arguments.content:
/* ============================================================
   App.css — DebugFlow dark developer-tool theme (polished)
   ============================================================ */

/* ── CSS Variables ─────────────────────────────────────────── */
:root {
  --bg:           #0d1117;
  --bg-panel:     #161b22;
  --bg-surface:   #1c2128;
  --bg-code:      #0a0d12;
  --border:       #30363d;
  --border-subtle:#21262d;
  --border-focus: #58a6ff;
  --text:         #c9d1d9;
  --text-muted:   #6e7681;
  --text-heading: #e6edf3;
  --accent:       #58a6ff;
  --accent-dark:  #1f6feb;
  --accent-glow:  rgba(88, 166, 255, 0.12);
  --green:        #3fb950;
  --green-bg:     #0d4429;
  --green-glow:   rgba(63, 185, 80, 0.1);
  --red:          #f85149;
  --red-bg:       #3b0a0a;
  --yellow:       #d29922;
  --yellow-bg:    #3d2d00;
  --diff-add-bg:  rgba(63, 185, 80, 0.12);
  --diff-del-bg:  rgba(248, 81, 73, 0.12);
  --diff-hunk:    #79c0ff;

  --font-sans:    -apple-system, "Segoe UI", system-ui, sans-serif;
  --font-mono:    "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

  --radius:       6px;
  --radius-lg:    10px;
  --radius-xl:    14px;
  --shadow-sm:    0 1px 3px rgba(0,0,0,.4);
  --shadow-md:    0 4px 12px rgba(0,0,0,.5);
  --transition:   0.15s ease;
}

/* ── Reset / Base ───────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 15px;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  min-height: 100vh;
}

/* Visually hidden helper for screen-reader labels */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ─────────────────────────────────────────────────── */
.app-header {
  background: var(--bg-panel);
  border-bottom: 1px solid var(--border);
  padding: 0 1.75rem;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 1px 0 var(--border-subtle), var(--shadow-sm);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.header-logo-wrap {
  width: 34px;
  height: 34px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--accent-dark) 0%, #0d3b7d 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
  box-shadow: 0 0 0 1px rgba(88,166,255,.2), var(--shadow-sm);
}

.header-text {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.header-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-heading);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.header-tagline {
  font-size: 0.72rem;
  color: var(--text-muted);
  letter-spacing: 0.02em;
  line-height: 1.2;
}

/* Backend status pill */
.backend-status {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.3rem 0.75rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-surface);
  transition: border-color var(--transition), color var(--transition);
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.backend-status--online  .status-dot { background: var(--green); box-shadow: 0 0 4px var(--green); }
.backend-status--offline .status-dot { background: var(--red); }
.backend-status--checking .status-dot { background: var(--yellow); animation: pulse 1.4s ease infinite; }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.backend-status--online  { color: var(--green);  border-color: rgba(63,185,80,.35); background: rgba(63,185,80,.06); }
.backend-status--offline { color: var(--red);    border-color: rgba(248,81,73,.35); }

/* ── Main layout ────────────────────────────────────────────── */
.app-main {
  max-width: 1260px;
  margin: 0 auto;
  padding: 1.75rem 1.75rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.input-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
  align-items: start;
}

@media (max-width: 860px) {
  .app-main { padding: 1.25rem 1rem 3rem; }
  .input-row { grid-template-columns: 1fr; }
}

/* ── Panels ─────────────────────────────────────────────────── */
.panel {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 1.1rem 1.35rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  box-shadow: var(--shadow-sm);
}

.panel--result {
  border-top: 2px solid var(--accent-dark);
  background: linear-gradient(180deg, rgba(31,111,235,.03) 0%, var(--bg-panel) 60px);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  min-height: 28px;
}

.panel-subheader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.panel-title {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.panel-title--lg {
  font-size: 0.8rem;
}

.panel-actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.panel-hint {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.4;
}

.panel-footer {
  margin-top: 0.25rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Buttons ─────────────────────────────────────────────────── */
.btn {
  cursor: pointer;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  transition: opacity var(--transition), background var(--transition),
              border-color var(--transition), color var(--transition),
              box-shadow var(--transition), transform var(--transition);
  white-space: nowrap;
  line-height: 1.2;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.btn:not(:disabled):active { transform: translateY(1px); }

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Primary — main CTA (Analyze, Generate Fix) */
.btn--primary {
  background: var(--accent-dark);
  color: #fff;
  border: 1px solid rgba(88,166,255,.3);
  box-shadow: 0 0 0 0 transparent;
  font-weight: 600;
}
.btn--primary:not(:disabled):hover {
  background: #2979d4;
  border-color: var(--accent);
  box-shadow: 0 0 8px rgba(88,166,255,.3);
}

/* Secondary — helper actions (Load Demo, demo presets) */
.btn--secondary {
  background: var(--bg-surface);
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--secondary:not(:disabled):hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-glow);
}

/* Ghost — low-emphasis (Clear, Show output) */
.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
}
.btn--ghost:not(:disabled):hover { color: var(--text); border-color: var(--border); }

/* Accent-green — Apply Fix (high-intent, destructive-ish) */
.btn--accent {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid rgba(63,185,80,.5);
  font-weight: 600;
}
.btn--accent:not(:disabled):hover {
  background: #154e24;
  border-color: var(--green);
  box-shadow: 0 0 8px rgba(63,185,80,.25);
}

/* Run tests — distinct teal/primary-blue tone */
.btn--run {
  background: linear-gradient(135deg, #0f3460 0%, var(--accent-dark) 100%);
  color: #fff;
  border: 1px solid rgba(88,166,255,.25);
  font-weight: 600;
}
.btn--run:not(:disabled):hover {
  background: linear-gradient(135deg, #1a4a80 0%, #2979d4 100%);
  border-color: rgba(88,166,255,.5);
  box-shadow: 0 0 8px rgba(88,166,255,.3);
}

.btn--sm {
  font-size: 0.75rem;
  padding: 0.3rem 0.65rem;
  border-radius: 5px;
}

.btn--lg {
  font-size: 0.92rem;
  padding: 0.6rem 1.3rem;
}

/* ── Textareas / Code editor ─────────────────────────────────── */
.code-textarea {
  width: 100%;
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  line-height: 1.6;
  padding: 0.85rem 1rem;
  resize: vertical;
  outline: none;
  tab-size: 4;
  transition: border-color var(--transition), box-shadow var(--transition);
  caret-color: var(--accent);
}

.code-textarea::placeholder {
  color: var(--text-muted);
  opacity: 0.6;
}

.code-textarea:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(88,166,255,.12);
}

.code-textarea--error {
  border-color: rgba(248,81,73,.3);
  background: #0c0a0a;
}

.code-textarea--error:focus {
  border-color: var(--red);
  box-shadow: 0 0 0 3px rgba(248,81,73,.12);
}

/* Char/line counter row */
.textarea-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: -0.25rem;
}

.analyze-row {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  flex-wrap: wrap;
  padding-top: 0.15rem;
}

/* ── Workflow Status ─────────────────────────────────────────── */
.workflow-status {
  display: flex;
  align-items: center;
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 0.9rem 1.5rem;
  overflow-x: auto;
  scrollbar-width: none;
  gap: 0;
  box-shadow: var(--shadow-sm);
}

.workflow-status::-webkit-scrollbar { display: none; }

.workflow-step {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}

.workflow-node {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  border: 2px solid var(--border);
  color: var(--text-muted);
  background: var(--bg-surface);
  flex-shrink: 0;
  transition: all var(--transition);
}

.workflow-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  white-space: nowrap;
  transition: color var(--transition);
  font-weight: 500;
}

.workflow-connector {
  width: 36px;
  height: 2px;
  margin: 0 0.4rem;
  border-radius: 1px;
  flex-shrink: 0;
  transition: background var(--transition);
}

.workflow-connector--done    { background: var(--green); }
.workflow-connector--pending { background: var(--border-subtle); }

/* Active step */
.workflow-step--active .workflow-node {
  border-color: var(--accent);
  background: rgba(31,111,235,.18);
  color: var(--accent);
  box-shadow: 0 0 0 3px rgba(88,166,255,.15);
}
.workflow-step--active .workflow-label {
  color: var(--accent);
  font-weight: 700;
}

/* Done step */
.workflow-step--done .workflow-node {
  border-color: var(--green);
  background: var(--green-bg);
  color: var(--green);
}
.workflow-step--done .workflow-label {
  color: var(--green);
}

/* ── Analysis Panel ──────────────────────────────────────────── */
.analysis-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

@media (max-width: 600px) {
  .analysis-grid { grid-template-columns: 1fr; }
}

.analysis-field {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.6rem 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  transition: border-color var(--transition);
}

.analysis-field:hover { border-color: var(--border); }

.analysis-field--wide {
  grid-column: 1 / -1;
}

.field--highlight {
  border-color: rgba(31,111,235,.4);
  background: rgba(31,111,235,.07);
}

.field--highlight:hover { border-color: var(--accent-dark); }

.field-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 600;
}

.field-value {
  font-size: 0.87rem;
  color: var(--text-heading);
  word-break: break-word;
  line-height: 1.5;
}

.field-value--mono {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: var(--accent);
}

/* Confidence badge */
.confidence-badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.25rem 0.7rem;
  border-radius: 999px;
  letter-spacing: 0.02em;
}

.confidence--high   { background: var(--green-bg);  color: var(--green);  border: 1px solid rgba(63,185,80,.4); }
.confidence--medium { background: var(--yellow-bg); color: var(--yellow); border: 1px solid rgba(210,153,34,.4); }
.confidence--low    { background: var(--red-bg);    color: var(--red);    border: 1px solid rgba(248,81,73,.4); }

/* ── Fix Panel ───────────────────────────────────────────────── */
.fix-explanation,
.fix-proposed-change {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
}

.subsection-title {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.explanation-text {
  font-size: 0.87rem;
  color: var(--text);
  line-height: 1.65;
}

/* Code tabs */
.code-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg-surface);
  border-radius: var(--radius) var(--radius) 0 0;
  padding: 0 0.25rem;
}

.code-tab {
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  font-family: var(--font-sans);
  transition: color var(--transition), border-color var(--transition);
  margin-bottom: -1px;
}

.code-tab:hover { color: var(--text); }

.code-tab--active {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 700;
}

/* Code blocks */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  line-height: 1.6;
  overflow-x: auto;
  white-space: pre;
  color: var(--text);
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.code-block::-webkit-scrollbar { height: 5px; }
.code-block::-webkit-scrollbar-track { background: transparent; }
.code-block::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* When tabs precede a code block, square the top corners */
.code-tabs + .code-block {
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}

.code-block--compact   { font-size: 0.77rem; padding: 0.75rem 0.9rem; }
.code-block--fixed     { border-color: rgba(63,185,80,.4); }
.code-block--stderr    { color: var(--red); }

/* Diff colouring */
.diff-add    { display: block; background: var(--diff-add-bg); color: var(--green); }
.diff-remove { display: block; background: var(--diff-del-bg); color: var(--red); }
.diff-hunk   { display: block; color: var(--diff-hunk); opacity: 0.8; }

.applied-notice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Test Results ────────────────────────────────────────────── */
.test-results {
  border-top: 1px solid var(--border);
  padding-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.test-summary-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.test-status-badge {
  font-size: 0.8rem;
  font-weight: 800;
  padding: 0.3rem 0.85rem;
  border-radius: var(--radius);
  letter-spacing: 0.04em;
}

.test-status-badge--pass {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid rgba(63,185,80,.4);
  box-shadow: 0 0 6px rgba(63,185,80,.15);
}

.test-status-badge--fail {
  background: var(--red-bg);
  color: var(--red);
  border: 1px solid rgba(248,81,73,.4);
  box-shadow: 0 0 6px rgba(248,81,73,.15);
}

.test-counts {
  font-size: 0.82rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.tests-passed { color: var(--green); font-weight: 600; }
.tests-failed { color: var(--red);   font-weight: 600; }
.tests-errors { color: var(--yellow); font-weight: 600; }

.return-code {
  font-size: 0.74rem;
  color: var(--text-muted);
  font-family: var(--font-mono);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  margin-left: auto;
}

.test-summary-text { }

.test-output {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.output-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.15rem;
}

/* ── Badges ─────────────────────────────────────────────────── */
.badge {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  letter-spacing: 0.03em;
}

.badge--green  { background: var(--green-bg);  color: var(--green);  border: 1px solid rgba(63,185,80,.4); }
.badge--yellow { background: var(--yellow-bg); color: var(--yellow); border: 1px solid rgba(210,153,34,.4); }

/* ── Divider label ───────────────────────────────────────────── */
.section-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-muted);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
}
.section-divider::before,
.section-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* ── Banners ─────────────────────────────────────────────────── */
.error-banner {
  background: var(--red-bg);
  border: 1px solid rgba(248,81,73,.5);
  border-radius: var(--radius);
  color: var(--red);
  font-size: 0.85rem;
  padding: 0.7rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  animation: slideDown 0.15s ease;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.error-banner strong { flex-shrink: 0; }

.error-banner-close {
  margin-left: auto;
  background: none;
  border: none;
  color: var(--red);
  cursor: pointer;
  font-size: 0.85rem;
  padding: 0.15rem 0.4rem;
  border-radius: 3px;
  flex-shrink: 0;
  transition: background var(--transition);
}
.error-banner-close:hover { background: rgba(248,81,73,.2); }

.warn-banner {
  background: var(--yellow-bg);
  border: 1px solid rgba(210,153,34,.5);
  border-radius: var(--radius);
  color: var(--yellow);
  font-size: 0.82rem;
  padding: 0.65rem 1rem;
}

.warn-banner code {
  background: rgba(0,0,0,.25);
  padding: 0.1rem 0.4rem;
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: 0.8em;
}

/* ── Info box ────────────────────────────────────────────────── */
.info-box--warning {
  background: var(--yellow-bg);
  border: 1px solid rgba(210,153,34,.5);
  border-radius: var(--radius);
  color: var(--yellow);
  font-size: 0.82rem;
  padding: 0.65rem 1rem;
}

/* ── Footer ─────────────────────────────────────────────────── */
.app-footer {
  text-align: center;
  font-size: 0.72rem;
  color: var(--text-muted);
  padding: 1.5rem 1rem;
  border-top: 1px solid var(--border);
  letter-spacing: 0.02em;
}

