/* ============================================================
   App.css — DebugFlow dark developer-tool theme (polished)
   ============================================================ */

/* ── CSS Variables ─────────────────────────────────────────── */
:root {
  --bg:           #0d1117;
  --bg-panel:     #161b22;
  --bg-surface:   #1c2128;
  --bg-code:      #0a0d12;
  --border:       #30363d;
  --border-subtle:#21262d;
  --border-focus: #58a6ff;
  --text:         #c9d1d9;
  --text-muted:   #6e7681;
  --text-heading: #e6edf3;
  --accent:       #58a6ff;
  --accent-dark:  #1f6feb;
  --accent-glow:  rgba(88, 166, 255, 0.12);
  --green:        #3fb950;
  --green-bg:     #0d4429;
  --green-glow:   rgba(63, 185, 80, 0.1);
  --red:          #f85149;
  --red-bg:       #3b0a0a;
  --yellow:       #d29922;
  --yellow-bg:    #3d2d00;
  --diff-add-bg:  rgba(63, 185, 80, 0.12);
  --diff-del-bg:  rgba(248, 81, 73, 0.12);
  --diff-hunk:    #79c0ff;

  --font-sans:    -apple-system, "Segoe UI", system-ui, sans-serif;
  --font-mono:    "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

  --radius:       6px;
  --radius-lg:    10px;
  --radius-xl:    14px;
  --shadow-sm:    0 1px 3px rgba(0,0,0,.4);
  --shadow-md:    0 4px 12px rgba(0,0,0,.5);
  --transition:   0.15s ease;
}

/* ── Reset / Base ───────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 15px;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  min-height: 100vh;
}

/* Visually hidden helper for screen-reader labels */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ─────────────────────────────────────────────────── */
.app-header {
  background: var(--bg-panel);
  border-bottom: 1px solid var(--border);
  padding: 0 1.75rem;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 1px 0 var(--border-subtle), var(--shadow-sm);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.header-logo-wrap {
  width: 34px;
  height: 34px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--accent-dark) 0%, #0d3b7d 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
  box-shadow: 0 0 0 1px rgba(88,166,255,.2), var(--shadow-sm);
}

.header-text {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.header-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-heading);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.header-tagline {
  font-size: 0.72rem;
  color: var(--text-muted);
  letter-spacing: 0.02em;
  line-height: 1.2;
}

/* Backend status pill */
.backend-status {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.3rem 0.75rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-surface);
  transition: border-color var(--transition), color var(--transition);
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.backend-status--online  .status-dot { background: var(--green); box-shadow: 0 0 4px var(--green); }
.backend-status--offline .status-dot { background: var(--red); }
.backend-status--checking .status-dot { background: var(--yellow); animation: pulse 1.4s ease infinite; }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.backend-status--online  { color: var(--green);  border-color: rgba(63,185,80,.35); background: rgba(63,185,80,.06); }
.backend-status--offline { color: var(--red);    border-color: rgba(248,81,73,.35); }

/* ── Main layout ────────────────────────────────────────────── */
.app-main {
  max-width: 1260px;
  margin: 0 auto;
  padding: 1.75rem 1.75rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.input-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
  align-items: start;
}

@media (max-width: 860px) {
  .app-main { padding: 1.25rem 1rem 3rem; }
  .input-row { grid-template-columns: 1fr; }
}

/* ── Panels ─────────────────────────────────────────────────── */
.panel {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 1.1rem 1.35rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  box-shadow: var(--shadow-sm);
}

.panel--result {
  border-top: 2px solid var(--accent-dark);
  background: linear-gradient(180deg, rgba(31,111,235,.03) 0%, var(--bg-panel) 60px);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  min-height: 28px;
}

.panel-subheader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.panel-title {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.panel-title--lg {
  font-size: 0.8rem;
}

.panel-actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.panel-hint {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.4;
}

.panel-footer {
  margin-top: 0.25rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Buttons ─────────────────────────────────────────────────── */
.btn {
  cursor: pointer;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  transition: opacity var(--transition), background var(--transition),
              border-color var(--transition), color var(--transition),
              box-shadow var(--transition), transform var(--transition);
  white-space: nowrap;
  line-height: 1.2;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.btn:not(:disabled):active { transform: translateY(1px); }

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Primary — main CTA (Analyze, Generate Fix) */
.btn--primary {
  background: var(--accent-dark);
  color: #fff;
  border: 1px solid rgba(88,166,255,.3);
  box-shadow: 0 0 0 0 transparent;
  font-weight: 600;
}
.btn--primary:not(:disabled):hover {
  background: #2979d4;
  border-color: var(--accent);
  box-shadow: 0 0 8px rgba(88,166,255,.3);
}

/* Secondary — helper actions (Load Demo, demo presets) */
.btn--secondary {
  background: var(--bg-surface);
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--secondary:not(:disabled):hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-glow);
}

/* Ghost — low-emphasis (Clear, Show output) */
.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
}
.btn--ghost:not(:disabled):hover { color: var(--text); border-color: var(--border); }

/* Accent-green — Apply Fix (high-intent, destructive-ish) */
.btn--accent {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid rgba(63,185,80,.5);
  font-weight: 600;
}
.btn--accent:not(:disabled):hover {
  background: #154e24;
  border-color: var(--green);
  box-shadow: 0 0 8px rgba(63,185,80,.25);
}

/* Run tests — distinct teal/primary-blue tone */
.btn--run {
  background: linear-gradient(135deg, #0f3460 0%, var(--accent-dark) 100%);
  color: #fff;
  border: 1px solid rgba(88,166,255,.25);
  font-weight: 600;
}
.btn--run:not(:disabled):hover {
  background: linear-gradient(135deg, #1a4a80 0%, #2979d4 100%);
  border-color: rgba(88,166,255,.5);
  box-shadow: 0 0 8px rgba(88,166,255,.3);
}

.btn--sm {
  font-size: 0.75rem;
  padding: 0.3rem 0.65rem;
  border-radius: 5px;
}

.btn--lg {
  font-size: 0.92rem;
  padding: 0.6rem 1.3rem;
}

/* ── Textareas / Code editor ─────────────────────────────────── */
.code-textarea {
  width: 100%;
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  line-height: 1.6;
  padding: 0.85rem 1rem;
  resize: vertical;
  outline: none;
  tab-size: 4;
  transition: border-color var(--transition), box-shadow var(--transition);
  caret-color: var(--accent);
}

.code-textarea::placeholder {
  color: var(--text-muted);
  opacity: 0.6;
}

.code-textarea:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(88,166,255,.12);
}

.code-textarea--error {
  border-color: rgba(248,81,73,.3);
  background: #0c0a0a;
}

.code-textarea--error:focus {
  border-color: var(--red);
  box-shadow: 0 0 0 3px rgba(248,81,73,.12);
}

/* Char/line counter row */
.textarea-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: -0.25rem;
}

.analyze-row {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  flex-wrap: wrap;
  padding-top: 0.15rem;
}

/* ── Workflow Status ─────────────────────────────────────────── */
.workflow-status {
  display: flex;
  align-items: center;
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 0.9rem 1.5rem;
  overflow-x: auto;
  scrollbar-width: none;
  gap: 0;
  box-shadow: var(--shadow-sm);
}

.workflow-status::-webkit-scrollbar { display: none; }

.workflow-step {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}

.workflow-node {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  border: 2px solid var(--border);
  color: var(--text-muted);
  background: var(--bg-surface);
  flex-shrink: 0;
  transition: all var(--transition);
}

.workflow-label {
  font-size: 0.75rem;
  color: var(--text-muted);
  white-space: nowrap;
  transition: color var(--transition);
  font-weight: 500;
}

.workflow-connector {
  width: 36px;
  height: 2px;
  margin: 0 0.4rem;
  border-radius: 1px;
  flex-shrink: 0;
  transition: background var(--transition);
}

.workflow-connector--done    { background: var(--green); }
.workflow-connector--pending { background: var(--border-subtle); }

/* Active step */
.workflow-step--active .workflow-node {
  border-color: var(--accent);
  background: rgba(31,111,235,.18);
  color: var(--accent);
  box-shadow: 0 0 0 3px rgba(88,166,255,.15);
}
.workflow-step--active .workflow-label {
  color: var(--accent);
  font-weight: 700;
}

/* Done step */
.workflow-step--done .workflow-node {
  border-color: var(--green);
  background: var(--green-bg);
  color: var(--green);
}
.workflow-step--done .workflow-label {
  color: var(--green);
}

/* ── Analysis Panel ──────────────────────────────────────────── */
.analysis-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

@media (max-width: 600px) {
  .analysis-grid { grid-template-columns: 1fr; }
}

.analysis-field {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.6rem 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  transition: border-color var(--transition);
}

.analysis-field:hover { border-color: var(--border); }

.analysis-field--wide {
  grid-column: 1 / -1;
}

.field--highlight {
  border-color: rgba(31,111,235,.4);
  background: rgba(31,111,235,.07);
}

.field--highlight:hover { border-color: var(--accent-dark); }

.field-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 600;
}

.field-value {
  font-size: 0.87rem;
  color: var(--text-heading);
  word-break: break-word;
  line-height: 1.5;
}

.field-value--mono {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: var(--accent);
}

/* Confidence badge */
.confidence-badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.25rem 0.7rem;
  border-radius: 999px;
  letter-spacing: 0.02em;
}

.confidence--high   { background: var(--green-bg);  color: var(--green);  border: 1px solid rgba(63,185,80,.4); }
.confidence--medium { background: var(--yellow-bg); color: var(--yellow); border: 1px solid rgba(210,153,34,.4); }
.confidence--low    { background: var(--red-bg);    color: var(--red);    border: 1px solid rgba(248,81,73,.4); }

/* ── Fix Panel ───────────────────────────────────────────────── */
.fix-explanation,
.fix-proposed-change {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
}

.subsection-title {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.explanation-text {
  font-size: 0.87rem;
  color: var(--text);
  line-height: 1.65;
}

/* Code tabs */
.code-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg-surface);
  border-radius: var(--radius) var(--radius) 0 0;
  padding: 0 0.25rem;
}

.code-tab {
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  font-family: var(--font-sans);
  transition: color var(--transition), border-color var(--transition);
  margin-bottom: -1px;
}

.code-tab:hover { color: var(--text); }

.code-tab--active {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 700;
}

/* Code blocks */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  line-height: 1.6;
  overflow-x: auto;
  white-space: pre;
  color: var(--text);
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.code-block::-webkit-scrollbar { height: 5px; }
.code-block::-webkit-scrollbar-track { background: transparent; }
.code-block::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* When tabs precede a code block, square the top corners */
.code-tabs + .code-block {
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}

.code-block--compact   { font-size: 0.77rem; padding: 0.75rem 0.9rem; }
.code-block--fixed     { border-color: rgba(63,185,80,.4); }
.code-block--stderr    { color: var(--red); }

/* Diff colouring */
.diff-add    { display: block; background: var(--diff-add-bg); color: var(--green); }
.diff-remove { display: block; background: var(--diff-del-bg); color: var(--red); }
.diff-hunk   { display: block; color: var(--diff-hunk); opacity: 0.8; }

.applied-notice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Test Results ────────────────────────────────────────────── */
.test-results {
  border-top: 1px solid var(--border);
  padding-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.test-summary-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.test-status-badge {
  font-size: 0.8rem;
