  --text:        #c9d1d9;
  --text-muted:  #6e7681;
  --text-heading:#e6edf3;
  --accent:      #58a6ff;
  --accent-dark: #1f6feb;
  --green:       #3fb950;
  --green-bg:    #0d4429;
  --red:         #f85149;
  --red-bg:      #3b0a0a;
  --yellow:      #d29922;
  --yellow-bg:   #3d2d00;
