.backend-status {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.78rem;
  padding: 0.3rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-surface);
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.backend-status--online  .status-dot { background: var(--green); }
.backend-status--offline .status-dot { background: var(--red); }
.backend-status--checking .status-dot { background: var(--yellow); }
.backend-status--online  { color: var(--green); border-color: var(--green-bg); }
.backend-status--offline { color: var(--red);   border-color: var(--red-bg); }

/* ── Main layout ────────────────────────────────────────────── */
.app-main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.5rem 1.5rem 3rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.input-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
}

@media (max-width: 860px) {
  .input-row {
    grid-template-columns: 1fr;
  }
}

/* ── Panels ─────────────────────────────────────────────────── */
.panel {
  background: var(--bg-panel);
