/* ============================================================
   App.css — DebugFlow dark developer-tool theme (polished)
   ============================================================ */

/* ── CSS Variables ─────────────────────────────────────────── */
:root {
  --bg:           #0d1117;
  --bg-panel:     #161b22;
  --bg-surface:   #1c2128;
  --bg-code:      #0a0d12;
  --border:       #30363d;
  --border-subtle:#21262d;
  --border-focus: #58a6ff;
  --text:         #c9d1d9;
  --text-muted:   #6e7681;
  --text-heading: #e6edf3;
  --accent:       #58a6ff;
  --accent-dark:  #1f6feb;
  --accent-glow:  rgba(88, 166, 255, 0.12);
  --green:        #3fb950;
  --green-bg:     #0d4429;
  --green-glow:   rgba(63, 185, 80, 0.1);
  --red:          #f85149;
  --red-bg:       #3b0a0a;
  --yellow:       #d29922;
  --yellow-bg:    #3d2d00;
  --diff-add-bg:  rgba(63, 185, 80, 0.12);
  --diff-del-bg:  rgba(248, 81, 73, 0.12);
  --diff-hunk:    #79c0ff;

  --font-sans:    -apple-system, "Segoe UI", system-ui, sans-serif;
  --font-mono:    "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

  --radius:       6px;
  --radius-lg:    10px;
  --radius-xl:    14px;
  --shadow-sm:    0 1px 3px rgba(0,0,0,.4);
  --shadow-md:    0 4px 12px rgba(0,0,0,.5);
  --transition:   0.15s ease;
}

/* ── Reset / Base ───────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 15px;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  min-height: 100vh;
}

/* Visually hidden helper for screen-reader labels */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Header ─────────────────────────────────────────────────── */
.app-header {
  background: var(--bg-panel);
  border-bottom: 1px solid var(--border);
  padding: 0 1.75rem;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 1px 0 var(--border-subtle), var(--shadow-sm);
}

.header-brand {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.header-logo-wrap {
  width: 34px;
  height: 34px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--accent-dark) 0%, #0d3b7d 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
  box-shadow: 0 0 0 1px rgba(88,166,255,.2), var(--shadow-sm);
}

.header-text {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.header-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-heading);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.header-tagline {
  font-size: 0.72rem;
  color: var(--text-muted);
  letter-spacing: 0.02em;
  line-height: 1.2;
}

/* Backend status pill */
.backend-status {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.3rem 0.75rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg-surface);
  transition: border-color var(--transition), color var(--transition);
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.backend-status--online  .status-dot { background: var(--green); box-shadow: 0 0 4px var(--green); }
.backend-status--offline .status-dot { background: var(--red); }
.backend-status--checking .status-dot { background: var(--yellow); animation: pulse 1.4s ease infinite; }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.backend-status--online  { color: var(--green);  border-color: rgba(63,185,80,.35); background: rgba(63,185,80,.06); }
.backend-status--offline { color: var(--red);    border-color: rgba(248,81,73,.35); }

/* ── Main layout ────────────────────────────────────────────── */
.app-main {
  max-width: 1260px;
  margin: 0 auto;
  padding: 1.75rem 1.75rem 4rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.input-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
  align-items: start;
}

@media (max-width: 860px) {
  .app-main { padding: 1.25rem 1rem 3rem; }
  .input-row { grid-template-columns: 1fr; }
}

/* ── Panels ─────────────────────────────────────────────────── */
.panel {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 1.1rem 1.35rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  box-shadow: var(--shadow-sm);
}

.panel--result {
  border-top: 2px solid var(--accent-dark);
  background: linear-gradient(180deg, rgba(31,111,235,.03) 0%, var(--bg-panel) 60px);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  min-height: 28px;
}

.panel-subheader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.panel-title {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.panel-title--lg {
  font-size: 0.8rem;
}

.panel-actions {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.panel-hint {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.4;
}

.panel-footer {
  margin-top: 0.25rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Buttons ─────────────────────────────────────────────────── */
.btn {
  cursor: pointer;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  transition: opacity var(--transition), background var(--transition),
              border-color var(--transition), color var(--transition),
              box-shadow var(--transition), transform var(--transition);
  white-space: nowrap;
  line-height: 1.2;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.btn:not(:disabled):active { transform: translateY(1px); }

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Primary — main CTA (Analyze, Generate Fix) */
.btn--primary {
  background: var(--accent-dark);
  color: #fff;
  border: 1px solid rgba(88,166,255,.3);
  box-shadow: 0 0 0 0 transparent;
  font-weight: 600;
}
.btn--primary:not(:disabled):hover {
  background: #2979d4;
  border-color: var(--accent);
  box-shadow: 0 0 8px rgba(88,166,255,.3);
}

/* Secondary — helper actions (Load Demo, demo presets) */
.btn--secondary {
  background: var(--bg-surface);
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--secondary:not(:disabled):hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-glow);
}

/* Ghost — low-emphasis (Clear, Show output) */
.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
}
.btn--ghost:not(:disabled):hover { color: var(--text); border-color: var(--border); }

/* Accent-green — Apply Fix (high-intent, destructive-ish) */
.btn--accent {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid rgba(63,185,80,.5);
  font-weight: 600;
}
.btn--accent:not(:disabled):hover {
  background: #154e24;
  border-color: var(--green);
  box-shadow: 0 0 8px rgba(63,185,80,.25);
}

/* Run tests — distinct teal/primary-blue tone */
.btn--run {
  background: linear-gradient(135deg, #0f3460 0%, var(--accent-dark) 100%);
  color: #fff;
  border: 1px solid rgba(88,166,255,.25);
  font-weight: 600;
}
.btn--run:not(:disabled):hover {
  background: linear-gradient(135deg, #1a4a80 0%, #2979d4 100%);
  border-color: rgba(88,166,255,.5);
  box-shadow: 0 0 8px rgba(88,166,255,.3);
}

.btn--sm {
  font-size: 0.75rem;
  padding: 0.3rem 0.65rem;
  border-radius: 5px;
}

.btn--lg {
  font-size: 0.92rem;
  padding: 0.6rem 1.3rem;
}

/* ── Textareas / Code editor ─────────────────────────────────── */
.code-textarea {
  width: 100%;
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
