.btn--primary:not(:disabled):hover {
  background: #2979d4;
  border-color: var(--accent);
  box-shadow: 0 0 8px rgba(88,166,255,.3);
}

/* Secondary — helper actions (Load Demo, demo presets) */
.btn--secondary {
  background: var(--bg-surface);
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--secondary:not(:disabled):hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-glow);
}

/* Ghost — low-emphasis (Clear, Show output) */
.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
}
.btn--ghost:not(:disabled):hover { color: var(--text); border-color: var(--border); }

/* Accent-green — Apply Fix (high-intent, destructive-ish) */
.btn--accent {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid rgba(63,185,80,.5);
  font-weight: 600;
}
.btn--accent:not(:disabled):hover {
  background: #154e24;
  border-color: var(--green);
  box-shadow: 0 0 8px rgba(63,185,80,.25);
}

/* Run tests — distinct teal/primary-blue tone */
.btn--run {
  background: linear-gradient(135deg, #0f3460 0%, var(--accent-dark) 100%);
  color: #fff;
  border: 1px solid rgba(88,166,255,.25);
  font-weight: 600;
}
.btn--run:not(:disabled):hover {
  background: linear-gradient(135deg, #1a4a80 0%, #2979d4 100%);
  border-color: rgba(88,166,255,.5);
  box-shadow: 0 0 8px rgba(88,166,255,.3);
}

.btn--sm {
  font-size: 0.75rem;
  padding: 0.3rem 0.65rem;
  border-radius: 5px;
}

/* Chip — pill-shaped compact selector for demo error presets */
.btn--chip {
  font-size: 0.72rem;
  font-weight: 600;
  padding: 0.22rem 0.7rem;
  border-radius: 999px;
  background: var(--bg-surface);
  color: var(--text-muted);
  border: 1px solid var(--border);
  letter-spacing: 0.01em;
}
.btn--chip:not(:disabled):hover {
  color: var(--red);
  border-color: rgba(248,81,73,.5);
  background: rgba(248,81,73,.06);
}

.btn--lg {
  font-size: 0.92rem;
  padding: 0.6rem 1.35rem;
  border-radius: var(--radius);
}

/* ── Textareas / Code editor ─────────────────────────────────── */
.code-textarea {
  width: 100%;
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  line-height: 1.6;
  padding: 0.85rem 1rem;
  resize: vertical;
  outline: none;
  tab-size: 4;
  transition: border-color var(--transition), box-shadow var(--transition);
  caret-color: var(--accent);
}

.code-textarea::placeholder {
  color: var(--text-muted);
  opacity: 0.6;
}

.code-textarea:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(88,166,255,.12);
}

.code-textarea--error {
  border-color: rgba(248,81,73,.3);
  background: #0c0a0a;
}

.code-textarea--error:focus {
  border-color: var(--red);
  box-shadow: 0 0 0 3px rgba(248,81,73,.12);
}

/* Char/line counter row */
.textarea-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: -0.25rem;
}

.analyze-row {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  flex-wrap: wrap;
  padding-top: 0.15rem;
}

/* ── Workflow Status ─────────────────────────────────────────── */
.workflow-status {
  display: flex;
  align-items: center;
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 1rem 1.5rem;
  overflow-x: auto;
  scrollbar-width: none;
  gap: 0;
  box-shadow: var(--shadow-sm);
  position: relative;
}

.workflow-status::-webkit-scrollbar { display: none; }

/* Pipeline label */
.workflow-status-label {
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  white-space: nowrap;
  margin-right: 1.25rem;
  padding-right: 1.25rem;
  border-right: 1px solid var(--border);
  flex-shrink: 0;
}

.workflow-step {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}

.workflow-node {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.68rem;
  font-weight: 700;
  border: 2px solid var(--border);
  color: var(--text-muted);
  background: var(--bg-surface);
  flex-shrink: 0;
  transition: all var(--transition);
  position: relative;
  z-index: 1;
}

.workflow-label {
  font-size: 0.73rem;
  color: var(--text-muted);
  white-space: nowrap;
  transition: color var(--transition);
  font-weight: 500;
}

/* Step icon — tiny monospace hint inside the node (via data-icon) */
.workflow-connector {
  flex: 1;
  min-width: 28px;
  max-width: 52px;
  height: 2px;
  margin: 0 0.3rem;
  border-radius: 1px;
  flex-shrink: 0;
  transition: background var(--transition);
  position: relative;
}

/* Dotted pattern on pending connectors for a "pipeline track" feel */
.workflow-connector--pending {
  background: repeating-linear-gradient(
    to right,
    var(--border-subtle) 0px,
    var(--border-subtle) 4px,
    transparent 4px,
    transparent 8px
  );
}

.workflow-connector--done {
  background: var(--green);
  box-shadow: 0 0 3px rgba(63,185,80,.4);
}

/* Active step */
.workflow-step--active .workflow-node {
  border-color: var(--accent);
  background: rgba(31,111,235,.2);
  color: var(--accent);
  box-shadow: 0 0 0 3px rgba(88,166,255,.15), 0 0 8px rgba(88,166,255,.1);
}
.workflow-step--active .workflow-label {
  color: var(--accent);
  font-weight: 700;
}

/* Done step */
.workflow-step--done .workflow-node {
  border-color: var(--green);
  background: var(--green-bg);
  color: var(--green);
  box-shadow: none;
}
.workflow-step--done .workflow-label {
  color: var(--green);
}

/* ── Analysis Panel ──────────────────────────────────────────── */
.analysis-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.6rem;
}

@media (max-width: 600px) {
  .analysis-grid { grid-template-columns: 1fr; }
}

.analysis-field {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.6rem 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  transition: border-color var(--transition);
}

.analysis-field:hover { border-color: var(--border); }

.analysis-field--wide {
  grid-column: 1 / -1;
}

.field--highlight {
  border-color: rgba(31,111,235,.4);
  background: rgba(31,111,235,.07);
}

.field--highlight:hover { border-color: var(--accent-dark); }

.field-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 600;
}

.field-value {
  font-size: 0.87rem;
  color: var(--text-heading);
  word-break: break-word;
  line-height: 1.5;
}

.field-value--mono {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: var(--accent);
}

/* Confidence badge */
.confidence-badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.25rem 0.7rem;
  border-radius: 999px;
  letter-spacing: 0.02em;
}

.confidence--high   { background: var(--green-bg);  color: var(--green);  border: 1px solid rgba(63,185,80,.4); }
.confidence--medium { background: var(--yellow-bg); color: var(--yellow); border: 1px solid rgba(210,153,34,.4); }
.confidence--low    { background: var(--red-bg);    color: var(--red);    border: 1px solid rgba(248,81,73,.4); }

/* ── Fix Panel ───────────────────────────────────────────────── */
.fix-explanation,
.fix-proposed-change {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
}

.subsection-title {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.explanation-text {
  font-size: 0.87rem;
  color: var(--text);
  line-height: 1.65;
}

/* Code tabs */
.code-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg-surface);
  border-radius: var(--radius) var(--radius) 0 0;
  padding: 0 0.25rem;
}

.code-tab {
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  font-family: var(--font-sans);
  transition: color var(--transition), border-color var(--transition);
  margin-bottom: -1px;
}

.code-tab:hover { color: var(--text); }

.code-tab--active {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 700;
}

/* Code blocks */
.code-block {
  background: var(--bg-code);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  line-height: 1.6;
  overflow-x: auto;
  white-space: pre;
  color: var(--text);
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.code-block::-webkit-scrollbar { height: 5px; }
.code-block::-webkit-scrollbar-track { background: transparent; }
.code-block::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* When tabs precede a code block, square the top corners */
.code-tabs + .code-block {
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
}

.code-block--compact   { font-size: 0.77rem; padding: 0.75rem 0.9rem; }
.code-block--fixed     { border-color: rgba(63,185,80,.4); }
.code-block--stderr    { color: var(--red); }

/* Diff colouring */
.diff-add    { display: block; background: var(--diff-add-bg); color: var(--green); }
.diff-remove { display: block; background: var(--diff-del-bg); color: var(--red); }
.diff-hunk   { display: block; color: var(--diff-hunk); opacity: 0.8; }

.applied-notice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* ── Test Results ────────────────────────────────────────────── */
.test-results {
  border-top: 1px solid var(--border);
  padding-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.test-summary-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.test-status-badge {
  font-size: 0.8rem;
  font-weight: 800;
  padding: 0.3rem 0.85rem;
  border-radius: var(--radius);
  letter-spacing: 0.04em;
}

.test-status-badge--pass {
  background: var(--green-bg);
  color: var(--green);
  border: 1px solid rgba(63,185,80,.4);
  box-shadow: 0 0 6px rgba(63,185,80,.15);
}

.test-status-badge--fail {
  background: var(--red-bg);
  color: var(--red);
  border: 1px solid rgba(248,81,73,.4);
  box-shadow: 0 0 6px rgba(248,81,73,.15);
}

.test-counts {
  font-size: 0.82rem;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.tests-passed { color: var(--green); font-weight: 600; }
.tests-failed { color: var(--red);   font-weight: 600; }
.tests-errors { color: var(--yellow); font-weight: 600; }

.return-code {
  font-size: 0.74rem;
  color: var(--text-muted);
  font-family: var(--font-mono);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  margin-left: auto;
}

.test-summary-text { }

.test-output {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.output-label {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
  font-weight: 700;
  margin-bottom: 0.15rem;
}

/* ── Badges ─────────────────────────────────────────────────── */
.badge {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
  letter-spacing: 0.03em;
}

.badge--green  { background: var(--green-bg);  color: var(--green);  border: 1px solid rgba(63,185,80,.4); }
.badge--yellow { background: var(--yellow-bg); color: var(--yellow); border: 1px solid rgba(210,153,34,.4); }

/* ── Divider label ───────────────────────────────────────────── */
.section-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--text-muted);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
}
.section-divider::before,
.section-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border);
}

/* ── Banners ─────────────────────────────────────────────────── */
.error-banner {
  background: var(--red-bg);
  border: 1px solid rgba(248,81,73,.5);
  border-radius: var(--radius);
  color: var(--red);
  font-size: 0.85rem;
  padding: 0.7rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  animation: slideDown 0.15s ease;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.error-banner strong { flex-shrink: 0; }

.error-banner-close {
  margin-left: auto;
  background: none;
  border: none;
  color: var(--red);
  cursor: pointer;
  font-size: 0.85rem;
  padding: 0.15rem 0.4rem;
  border-radius: 3px;
  flex-shrink: 0;
  transition: background var(--transition);
}
.error-banner-close:hover { background: rgba(248,81,73,.2); }

.warn-banner {
  background: var(--yellow-bg);
  border: 1px solid rgba(210,153,34,.5);
  border-radius: var(--radius);
  color: var(--yellow);
  font-size: 0.82rem;
  padding: 0.65rem 1rem;
}

.warn-banner code {
  background: rgba(0,0,0,.25);
  padding: 0.1rem 0.4rem;
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: 0.8em;
}

/* ── Info box ────────────────────────────────────────────────── */
.info-box--warning {
  background: var(--yellow-bg);
  border: 1px solid rgba(210,153,34,.5);
  border-radius: var(--radius);
  color: var(--yellow);
  font-size: 0.82rem;
  padding: 0.65rem 1rem;
}

/* ── Footer ─────────────────────────────────────────────────── */
.app-footer {
  text-align: center;
  font-size: 0.72rem;
  color: var(--text-muted);
  padding: 1.5rem 1rem;
  border-top: 1px solid var(--border);
  letter-spacing: 0.02em;
}

